        return `<div class="deck-row">
          <span class="dr-cost">${def.cost}</span>
          <span class="dr-name">${esc(def.name)}${entry.upgraded ? ' <span class="dr-up">★</span>' : ''} ${entry.count > 1 ? `<span class="faint">×${entry.count}</span>` : ''}</span>
          <span class="dr-row">${ROW_SHORT[def.row]}</span>
          <span class="dr-stats">⚔${def.atk + (entry.upgraded ? 1 : 0)} ♥${def.hp + (entry.upgraded ? 1 : 0)}</span>
        </div>`
      }).join('')}
    </div>`
  return shell({ title: 'Il tuo mazzo', subtitle: `${run.deck.length} carte · ${FACTION_BY_ID[run.factionId].name}`, body, wide: true, actions: '<button type="button" class="btn" data-maction="close">Chiudi</button>' })
}

function deckPickerModal(modal) {
  const run = state.run
  if (!run) {
    return shell({ title: modal.title || 'Scegli una carta', body: '<p>Nessuna spedizione attiva.</p>', actions: '<button type="button" class="btn ghost" data-maction="close">Annulla</button>' })
  }
  const eligible = modal.mode === 'upgrade' ? run.deck.filter((c) => !c.upgraded) : [...run.deck]
  const body = `
    <p>${esc(modal.subtitle || (modal.mode === 'upgrade' ? 'Scegli una carta da potenziare.' : 'Scegli una carta da rimuovere dal mazzo.'))}</p>
    ${modal.source === 'shop' && modal.cost ? `<p class="dark-text" style="color:var(--gold-soft);font-size:12px">Costo: ${modal.cost} oro</p>` : ''}
    ${eligible.length ? `<div class="deck-browser">
      ${eligible.map((inst) => {
        const def = getCard(inst.id)
        return cardFaceHTML(def, {
          upgraded: inst.upgraded,
          tag: 'button',
          attrs: `data-maction="pick-deck" data-uid="${inst.uid}" aria-label="${esc(def.name)}"`,
        })
      }).join('')}
    </div>` : '<div class="empty-state">Nessuna carta disponibile per questa azione.</div>'}
    <div class="modal-actions"><button type="button" class="btn ghost" data-maction="close">Annulla</button></div>`
  return shell({ title: modal.title || (modal.mode === 'upgrade' ? 'Affina una carta' : 'Rimuovi una carta'), subtitle: 'Il tuo mazzo', body, wide: true })
}

function cardModal(modal) {
  const def = getCard(modal.cardId)
  if (!def) {
    return shell({ title: 'Carta', body: '<p>Carta non trovata.</p>', actions: '<button type="button" class="btn" data-maction="close">Chiudi</button>' })
  }
  const unit = modal.unit
  const faction = FACTION_BY_ID[def.faction]
  const keywords = (def.keywords || []).map((k) => k === 'perfora' ? 'Perfora: il danno in eccesso colpisce il Morale.' : k).join(' ')
  const body = `
    <div style="width:min(190px,58vw);margin:0 auto 16px">${cardFaceHTML(def, { upgraded: modal.upgraded })}</div>
    <p>${esc(def.text)}</p>
    ${keywords ? `<p class="gold" style="margin-top:8px;font-size:12px">${esc(keywords)}</p>` : ''}
    <div class="keyword-grid" style="margin-top:12px">
      <div class="keyword"><strong>Fazione</strong><span>${faction.emblem} ${esc(faction.name)}</span></div>
      <div class="keyword"><strong>Riga</strong><span>${ROW_SHORT[def.row]}</span></div>
      <div class="keyword"><strong>Costo</strong><span>${def.cost} Comando</span></div>
      <div class="keyword"><strong>Statistiche base</strong><span>⚔ ${def.atk} · ♥ ${def.hp}${modal.upgraded ? ' · ★ +1/+1' : ''}</span></div>
    </div>
    ${unit ? `<div class="keyword" style="margin-top:10px"><strong>In campo</strong><span>⚔ ${unit.atk} · ♥ ${unit.hp}/${unit.maxHp}${unit.shield ? ` · ◈ Scudo ${unit.shield}` : ''}${unit.upgraded ? ' · ★ Potenziata' : ''}</span></div>` : ''}
    <div class="modal-actions"><button type="button" class="btn" data-maction="close">Chiudi</button></div>`
  return shell({ title: def.name, subtitle: `${RARITY[def.rarity].label} · ${ROW_SHORT[def.row]}`, body })
}

function logModal() {
  const entries = state.battle?.log || []
  const body = entries.length
    ? `<div class="deck-list">${[...entries].reverse().slice(0, 40).map((entry) => `<div class="deck-row" style="display:block;font-size:11.5px;color:var(--muted)">${esc(entry)}</div>`).join('')}</div>`
    : '<div class="empty-state">Nessun evento registrato.</div>'
  return shell({ title: 'Registro', subtitle: 'Ultimi eventi', body, wide: true, actions: '<button type="button" class="btn" data-maction="close">Chiudi</button>' })
}

import {
  BANNER_BY_ID,
  FACTION_BY_ID,
  FACTIONS,
  RARITY,
  getCard,
  unlockedCards,
} from './data.js'
import {
  DECK_LIMIT,
  clamp,
  clearSavedRun,
  completeNode,
  createRun,
  endRun,
  eventById,
  findNode,
  hasBanner,
  healRun,
  loadMeta,
  loadSavedRun,
  makeCardInstance,
  playSound,
  pickBannerOptions,
  saveMeta,
  saveRun,
  shuffle,
  state,
} from './core.js'
import { endTurn, playPlayerCard, setBattleHooks, startBattle } from './battle.js'
import { render, renderModal, showToast } from './ui.js'

/* ═══════════════════════════════════════════════════════════
   NAVIGAZIONE E STATO
   ═══════════════════════════════════════════════════════════ */
function beginRun(factionId) {
  const faction = FACTION_BY_ID[factionId]
  if (!faction) return
  clearSavedRun()
  state.run = createRun(factionId)
  state.battle = null
  state.selectedCard = null
  state.reward = null
  state.shopNode = null
  state.eventNode = null
  state.eventResult = null
  state.campNode = null
  state.modal = null
  state.screen = 'map'
  saveRun()
  render()
  playSound('map')
  showToast(`La spedizione di ${faction.name} ha inizio.`, 'good')
}

function exitBattleToTitle() {
  if (state.run) saveRun()
  state.battle = null
  state.selectedCard = null
  state.reward = null
  state.shopNode = null
  state.eventNode = null
  state.eventResult = null
  state.campNode = null
  state.modal = null
  state.run = null
  state.screen = 'title'
  render()
  playSound('click')
}

function goTitle() {
  if (state.run) saveRun()
  state.run = null
  state.battle = null
  state.selectedCard = null
  state.reward = null
  state.shopNode = null
  state.eventNode = null
  state.eventResult = null
  state.campNode = null
  state.modal = null
  state.screen = 'title'
  render()
  playSound('click')
}

function startNode(nodeId) {
  const run = state.run
  if (!run) return
  const node = findNode(nodeId)
  if (!node || node.floor !== run.floor) {
    showToast('Questa tappa non è disponibile.', 'bad')
    return
  }
  state.modal = null
  if (node.type === 'battle' || node.type === 'elite' || node.type === 'boss') {
    state.screen = 'battle'
    state.selectedCard = null
    startBattle(node)
    render()
    playSound('play')
    return
  }
  if (node.type === 'event') {
    state.eventNode = node
    state.eventResult = null
    state.screen = 'event'
    render()
    playSound('click')
    return
  }
  if (node.type === 'shop') {
    ensureShop(node)
    state.shopNode = node
    state.screen = 'shop'
    render()
    playSound('map')
    return
  }
  if (node.type === 'camp') {
    state.campNode = node
    state.screen = 'camp'
    render()
    playSound('map')
  }
}

function completeNodeFlow(node, message, sound = 'map') {
  if (!node) {
    state.screen = 'map'
    render()
    return
  }
  const result = completeNode(node)
  if (result === 'finished') {
    finishRunNow(true, 'vittoria')
    return
  }
  state.screen = 'map'
  state.modal = null
  render()
  playSound(sound)
  if (message) showToast(message, 'good')
}

/* ═══════════════════════════════════════════════════════════
   MERCANTE / ACCAMPAMENTO / EVENTI
   ═══════════════════════════════════════════════════════════ */
function ensureShop(node) {
  const run = state.run
  if (!run) return
  if (!node.stock) {
    const pool = shuffle(unlockedCards(run.factionId))
    node.stock = pool.slice(0, 3).map((def) => ({
      cardId: def.id,
      price: RARITY[def.rarity].cost,
      sold: false,
    }))
  }
  if (!node.services) node.services = { heal: false, remove: false, upgrade: false }
  saveRun()
}

function buyShopCard(index) {
  const run = state.run
  const node = state.shopNode
  if (!run || !node) return
  const item = node.stock?.[index]
  if (!item || item.sold) return
  const def = getCard(item.cardId)
  if (!def) return
  if (run.deck.length >= DECK_LIMIT) return showToast('Il mazzo è pieno.', 'bad')
  if (run.gold < item.price) return showToast('Oro insufficiente.', 'bad')
  run.gold -= item.price
  run.deck.push(makeCardInstance(def.id))
  item.sold = true
  saveRun()
  playSound('gold')
  showToast(`${def.name} entra nel mazzo. −${item.price} oro`, 'good')
  render()
}

function shopHeal() {
  const run = state.run
  const node = state.shopNode
  if (!run || !node) return
  if (node.services.heal) return
  if (run.gold < 25) return showToast('Oro insufficiente.', 'bad')
  if (run.morale >= run.maxMorale) return showToast('Il Morale è già al massimo.', 'bad')
  run.gold -= 25
  const healed = healRun(run, 12)
  node.services.heal = true
  saveRun()
  playSound('heal')
  showToast(`Recuperi ${healed} Morale. −25 oro`, 'good')
  render()
}

function shopRemove() {
  const run = state.run
  const node = state.shopNode
  if (!run || !node) return
  if (node.services.remove) return
  if (run.gold < 50) return showToast('Oro insufficiente.', 'bad')
  if (run.deck.length <= 8) return showToast('Il mazzo è già troppo piccolo.', 'bad')
  openDeckPicker({
    mode: 'remove',
    source: 'shop',
    nodeId: node.id,
    cost: 50,
    service: 'remove',
    title: 'Rimuovi una carta · 50 oro',
    subtitle: 'Scegli la carta da togliere dal mazzo. L’oro verrà speso solo alla conferma.',
  })
}

function shopUpgrade() {
  const run = state.run
  const node = state.shopNode
  if (!run || !node) return
  if (node.services.upgrade) return
  if (run.gold < 60) return showToast('Oro insufficiente.', 'bad')
  if (!run.deck.some((c) => !c.upgraded)) return showToast('Tutte le carte sono già potenziate.', 'bad')
  openDeckPicker({
    mode: 'upgrade',
    source: 'shop',
    nodeId: node.id,
    cost: 60,
    service: 'upgrade',
    title: 'Potenzia una carta · 60 oro',
    subtitle: 'La carta scelta ottiene +1 ATK e +1 HP. L’oro verrà speso solo alla conferma.',
  })
}

function campRest() {
  const run = state.run
  const node = state.campNode
  if (!run || !node) return
  if (run.morale >= run.maxMorale) return showToast('Sei già in pieno vigore.', 'bad')
  const amount = Math.max(8, Math.round(run.maxMorale * 0.3))
  const healed = healRun(run, amount)
  playSound('heal')
  completeNodeFlow(node, `Il riposo ti restituisce ${healed} Morale.`, 'heal')
}

function campUpgrade() {
  const run = state.run
  const node = state.campNode
  if (!run || !node) return
  if (!run.deck.some((c) => !c.upgraded)) return showToast('Tutte le carte sono già potenziate.', 'bad')
  openDeckPicker({
    mode: 'upgrade',
    source: 'camp',
    nodeId: node.id,
    title: 'Affina una carta',
    subtitle: 'La carta scelta ottiene +1 ATK e +1 HP. Potrai ripartire subito dopo.',
  })
}

function campRemove() {
  const run = state.run
  const node = state.campNode
  if (!run || !node) return
  if (run.deck.length <= 8) return showToast('Il mazzo è già troppo piccolo.', 'bad')
  openDeckPicker({
    mode: 'remove',
    source: 'camp',
    nodeId: node.id,
    title: 'Medita e lascia andare',
    subtitle: 'Scegli la carta da rimuovere dal mazzo. Potrai ripartire subito dopo.',
  })
}

function chooseEventOption(index) {
  const run = state.run
  const node = state.eventNode
  if (!run || !node) return
  const event = eventById(node.eventId)
  const option = event.options[index]
  if (!option) return
  if (option.can && !option.can(run)) {
    showToast('Non hai i requisiti per questa scelta.', 'bad')
    return
  }
  const result = option.apply(run)
  state.eventResult = result || 'La strada riprende.'
  playSound('map')
  render()
}

function eventContinue() {
  const node = state.eventNode
  completeNodeFlow(node, 'La strada continua.', 'map')
}

/* ═══════════════════════════════════════════════════════════
   RICOMPENSE / FINE BATTAGLIA
   ═══════════════════════════════════════════════════════════ */
function handleBattleWin(node) {
  const b = state.battle
  const run = state.run
  if (!b || !run) return
  run.stats.battlesWon += 1
  if (node.type === 'elite') run.stats.elitesWon += 1
  run.morale = clamp(b.player.morale, 0, run.maxMorale)

  const gold = Math.round(node.gold * (hasBanner(run, 'banner_gold') ? 1.3 : 1))
  run.gold += gold
  if (hasBanner(run, 'banner_supplies')) healRun(run, 6)

  state.battle = null
  state.selectedCard = null
  state.modal = null

  if (node.type === 'boss') {
    finishRunNow(true, 'vittoria')
    return
  }

  const cardOptions = run.deck.length < DECK_LIMIT ? cardRewardOptions(run, 3) : []
  const bannerOptions = node.type === 'elite' ? pickBannerOptions(run, 2) : []
  state.reward = {
    node,
    gold,
    cards: cardOptions,
    bannerOptions,
    stage: cardOptions.length ? 'card' : bannerOptions.length ? 'banner' : 'done',
  }
  if (state.reward.stage === 'done') {
    completeReward()
    return
  }
  state.screen = 'reward'
  render()
  playSound('gold')
  showToast(`+${gold} oro${hasBanner(run, 'banner_supplies') ? ' · Provviste: +6 Morale' : ''}`, 'gold')
}

function handleBattleLose() {
  if (state.run) state.run.morale = 0
  finishRunNow(false, 'sconfitta')
}

function pickReward(cardId) {
  const reward = state.reward
  const run = state.run
  if (!reward || !run || reward.stage !== 'card') return
  const def = getCard(cardId)
  if (!def) return
  if (run.deck.length < DECK_LIMIT) {
    run.deck.push(makeCardInstance(def.id))
    showToast(`${def.name} entra nel mazzo.`, 'good')
    playSound('unlock')
  } else {
    showToast('Il mazzo è pieno: la carta non può essere aggiunta.', 'bad')
  }
  if (reward.bannerOptions.length) {
    reward.stage = 'banner'
    render()
  } else {
    completeReward()
  }
}

function skipReward() {
  const reward = state.reward
  if (!reward) return
  if (reward.bannerOptions.length) {
    reward.stage = 'banner'
    render()
  } else {
    completeReward()
  }
}

function pickBanner(bannerId) {
  const reward = state.reward
  const run = state.run
  const banner = BANNER_BY_ID[bannerId]
  if (!reward || !run || !banner) return
  if (!run.banners.includes(banner.id)) {
    run.banners.push(banner.id)
    if (banner.id === 'banner_courage') {
      run.maxMorale += 6
      healRun(run, 6)
    }
    playSound('unlock')
    showToast(`Stendardo ottenuto: ${banner.name}`, 'good')
  }
  completeReward()
}

function completeReward() {
  const reward = state.reward
  if (!reward) return
  const node = reward.node
  state.reward = null
  completeNodeFlow(node, 'Tappa completata. La strada prosegue.', 'map')
}

function finishRunNow(victory, reason) {
  const summary = endRun(victory, reason)
  if (!summary) {
    state.screen = 'title'
    render()
    return
  }
  state.lastRun = summary
  state.battle = null
  state.selectedCard = null
  state.reward = null
  state.shopNode = null
  state.eventNode = null
  state.eventResult = null
  state.campNode = null
  state.modal = null
  state.screen = 'runEnd'
  render()
  playSound(victory ? 'win' : 'lose')
}

/* ═══════════════════════════════════════════════════════════
   MODALI
   ═══════════════════════════════════════════════════════════ */
function openHelp() {
  state.modal = { type: 'help' }
  renderModal()
  playSound('click')
}

function openDeckView() {
  state.modal = { type: 'deck' }
  renderModal()
  playSound('click')
}

function openMenu() {
  state.modal = { type: 'menu', battle: state.screen === 'battle' }
  renderModal()
  playSound('click')
}

function openLog() {
  state.modal = { type: 'log' }
  renderModal()
  playSound('click')
}

function openDeckPicker(options) {
  state.modal = { type: 'deck-picker', ...options }
  renderModal()
  playSound('click')
}

function openConfirm(options) {
  state.modal = { type: 'confirm', ...options }
  renderModal()
  playSound('click')
}

function closeModal() {
  state.modal = null
  renderModal()
}

function handleModalAction(action, data) {
  if (action === 'close') {
    closeModal()
    return
  }
  if (action === 'help') {
    openHelp()
    return
  }
  if (action === 'deck') {
    openDeckView()
    return
  }
  if (action === 'log') {
    openLog()
    return
  }
  if (action === 'title') {
    if (state.battle) {
      openConfirm({
        title: 'Tornare al titolo?',
        text: 'La battaglia in corso andrà persa. La spedizione resta salvata all’ultima tappa completata.',
        confirmLabel: 'Torna al titolo',
        action: 'exit-battle-title',
      })
    } else {
      closeModal()
      goTitle()
    }
    return
  }
  if (action === 'abandon') {
    if (!state.run) {
      closeModal()
      return
    }
    openConfirm({
      title: 'Abbandonare la spedizione?',
      text: 'La run termina subito e ottieni gli Echi accumulati fino a qui. Le carte sbloccate restano per sempre.',
      confirmLabel: 'Abbandona',
      action: 'abandon',
    })
    return
  }
  if (action === 'confirm') {
    const modal = state.modal
    if (!modal || modal.type !== 'confirm') return
    const { action: confirmAction, payload } = modal
    closeModal()
    if (confirmAction === 'abandon') finishRunNow(false, 'abbandonata')
    else if (confirmAction === 'overwrite-run' && payload?.factionId) beginRun(payload.factionId)
    else if (confirmAction === 'exit-battle-title') exitBattleToTitle()
    return
  }
  if (action === 'pick-deck') {
    handleDeckPick(data.uid)
  }
}

function handleDeckPick(uid) {
  const modal = state.modal
  const run = state.run
  if (!modal || modal.type !== 'deck-picker' || !run) return
  const index = run.deck.findIndex((c) => c.uid === uid)
  if (index < 0) return
  const inst = run.deck[index]

  if (modal.mode === 'remove' && run.deck.length <= 8) {
    closeModal()
    showToast('Il mazzo deve mantenere almeno 8 carte.', 'bad')
    render()
    return
  }
  if (modal.mode === 'upgrade' && inst.upgraded) {
    closeModal()
    showToast('Questa carta è già potenziata.', 'bad')
    render()
    return
  }

  if (modal.source === 'shop') {
    const node = findNode(modal.nodeId)
    if (!node || !node.services || node.services[modal.service]) {
      closeModal()
      showToast('Servizio non più disponibile.', 'bad')
      render()
      return
    }
    if (run.gold < modal.cost) {
      closeModal()
      showToast('Oro insufficiente.', 'bad')
      render()
      return
    }
    if (modal.mode === 'remove') run.deck.splice(index, 1)
    else inst.upgraded = true
    run.gold -= modal.cost
    node.services[modal.service] = true
    saveRun()
    closeModal()
    playSound(modal.mode === 'remove' ? 'click' : 'unlock')
    showToast(modal.mode === 'remove' ? 'Carta rimossa dal mazzo. −50 oro' : 'Carta potenziata. −60 oro', 'good')
    render()
    return
  }

  if (modal.source === 'camp') {
    const node = findNode(modal.nodeId)
    if (modal.mode === 'remove') run.deck.splice(index, 1)
    else inst.upgraded = true
    closeModal()
    playSound(modal.mode === 'remove' ? 'click' : 'unlock')
    completeNodeFlow(node, modal.mode === 'remove' ? 'Hai lasciato andare una carta.' : 'La carta è stata affinata.', modal.mode === 'remove' ? 'map' : 'unlock')
    return
  }

  closeModal()
  render()
}

/* ═══════════════════════════════════════════════════════════
   AZIONI
   ═══════════════════════════════════════════════════════════ */
function handleAction(action, data) {
  switch (action) {
    case 'show-title': goTitle(); return
    case 'show-factions':
      state.modal = null
      state.screen = 'factions'
      render()
      playSound('click')
      return
    case 'continue-run': {
      const saved = loadSavedRun()
      if (!saved) {
        showToast('Nessuna spedizione salvata.', 'bad')
        return
      }
      state.run = saved
      state.battle = null
      state.modal = null
      state.screen = 'map'
      render()
      playSound('map')
      showToast(`Spedizione ripresa: ${FACTION_BY_ID[saved.factionId].name}.`, 'good')
      return
    }
    case 'start-run': {
      const factionId = data.faction
      if (!FACTION_BY_ID[factionId]) return
      if (loadSavedRun()) {
        openConfirm({
          title: 'Spedizione in corso',
          text: 'Hai una spedizione salvata. Iniziarne una nuova la sostituirà e la vecchia non potrà essere recuperata.',
          confirmLabel: 'Inizia comunque',
          action: 'overwrite-run',
          payload: { factionId },
        })
      } else {
        beginRun(factionId)
      }
      return
    }
    case 'show-archive':
      state.modal = null
      state.archiveFaction = state.run?.factionId || state.lastRun?.factionId || 'greece'
      state.screen = 'archive'
      render()
      playSound('click')
      return
    case 'archive-tab':
      if (FACTION_BY_ID[data.faction]) {
        state.archiveFaction = data.faction
        render()
        playSound('click')
      }
      return
    case 'unlock-card': {
      const def = getCard(data.card)
      if (!def) return
      if (state.meta.unlocked[def.faction]?.includes(def.id)) return
      const cost = RARITY[def.rarity].cost
      if (state.meta.echoes < cost) {
        showToast('Non hai abbastanza Echi.', 'bad')
        return
      }
      state.meta.echoes -= cost
      state.meta.unlocked[def.faction].push(def.id)
      saveMeta()
      playSound('unlock')
      showToast(`${def.name} sbloccata! −${cost} Echi`, 'good')
      render()
      return
    }
    case 'view-card': {
      const def = getCard(data.card)
      if (!def) return
      state.modal = { type: 'card', cardId: def.id, upgraded: false }
      renderModal()
      playSound('click')
      return
    }
    case 'toggle-sound':
      state.meta.sound = !state.meta.sound
      saveMeta()
      playSound('click')
      render()
      return
    case 'open-help': openHelp(); return
    case 'open-deck': openDeckView(); return
    case 'open-run-menu':
    case 'battle-menu': openMenu(); return
    case 'battle-log': openLog(); return
    case 'enter-node': startNode(data.node); return
    case 'leave-shop': {
      const node = state.shopNode
      completeNodeFlow(node, 'Riprendi il cammino.', 'map')
      return
    }
    case 'buy-card': buyShopCard(Number(data.index)); return
    case 'shop-heal': shopHeal(); return
    case 'shop-remove': shopRemove(); return
    case 'shop-upgrade': shopUpgrade(); return
    case 'camp-rest': campRest(); return
    case 'camp-upgrade': campUpgrade(); return
    case 'camp-remove': campRemove(); return
    case 'leave-camp': {
      const node = state.campNode
      completeNodeFlow(node, 'Prosegui senza riposare.', 'map')
      return
    }
    case 'event-option': chooseEventOption(Number(data.index)); return
    case 'event-continue': eventContinue(); return
    case 'select-card': {
      const b = state.battle
      if (!b) return
      if (b.busy || b.phase !== 'player') {
        showToast('Attendi la fine della risoluzione.', 'bad')
        return
      }
      const index = Number(data.index)
      if (!b.player.hand[index]) return
      state.selectedCard = state.selectedCard === index ? null : index
      render()
      playSound('click')
      return
    }
    case 'slot': {
      const b = state.battle
      if (!b) return
      const side = data.side
      const row = data.row
      const col = Number(data.col)
      if (state.selectedCard != null) {
        if (side !== 'player') {
          showToast('Puoi schierare solo dalla tua parte del campo.', 'bad')
          return
        }
        const result = playPlayerCard(state.selectedCard, row, col)
        if (!result.ok) {
          showToast(result.message || 'Mossa non valida.', 'bad')
          return
        }
        return
      }
      const unit = b[side]?.units?.[row]?.[col]
      if (unit) {
        state.modal = {
          type: 'unit',
          cardId: unit.cardId,
          upgraded: unit.upgraded,
          unit: { ...unit },
        }
        renderModal()
        playSound('click')
      }
      return
    }
    case 'end-turn':
      endTurn().catch((error) => {
        console.error(error)
        showToast('Errore durante la risoluzione del turno.', 'bad')
      })
      return
    case 'pick-reward': pickReward(data.card); return
    case 'skip-reward': skipReward(); return
    case 'pick-banner': pickBanner(data.banner); return
    case 'run-end-factions':
      state.modal = null
      state.screen = 'factions'
      render()
      playSound('click')
      return
    case 'run-end-archive':
      state.archiveFaction = state.lastRun?.factionId || 'greece'
      state.modal = null
      state.screen = 'archive'
      render()
      playSound('click')
      return
    case 'run-end-title':
      state.modal = null
      state.screen = 'title'
      render()
      playSound('click')
      return
    default:
      return
  }
}

