  window.__echi = {
    state,
    getCard,
    FACTIONS,
    beginRun,
    startNode,
    playPlayerCard,
    endTurn,
    render,
    finishRunNow,
    addEchoes(amount) {
      state.meta.echoes = Math.max(0, state.meta.echoes + Number(amount || 0))
      saveMeta()
      render()
    },
    unlockAll() {
      for (const f of FACTIONS) state.meta.unlocked[f.id] = f.core.concat(f.locked)
      saveMeta()
      render()
    },
  }
}

