/* ───────────────────────── map ───────────────────────── */
.map-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin: 8px 0 18px;
  flex-wrap: wrap;
}
.map-head h1 { font-size: clamp(26px, 5vw, 42px); }
.map-head p { color: var(--muted); margin-top: 5px; font-size: 13px; }
.map-faction {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(20,28,39,.7);
  font-size: 12px;
}
.map-faction .em { font-size: 18px; }

.map-wrap {
  position: relative;
  display: flex;
  flex-direction: column-reverse;
  gap: 10px;
  padding: 15px 14px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(600px 300px at 50% 0%, rgba(217,176,95,.05), transparent 70%),
    rgba(12, 18, 26, .65);
  box-shadow: inset 0 0 60px rgba(0,0,0,.22);
}
.map-wrap::before {
  content: '';
  position: absolute;
  top: 24px; bottom: 24px; left: 33px;
  border-left: 1px dashed rgba(217,176,95,.22);
  pointer-events: none;
}
.floor-row {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 10px;
  position: relative;
}
.floor-num {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: #0d141d;
  font-family: var(--serif);
  font-size: 12px;
  color: var(--faint);
  position: relative;
  z-index: 1;
  margin-top: 6px;
}
.floor-row.current .floor-num { border-color: var(--gold); color: var(--gold-soft); box-shadow: 0 0 18px rgba(217,176,95,.22); }
.floor-row.cleared .floor-num { color: var(--ok); border-color: rgba(111,207,151,.45); }
.floor-nodes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
.floor-nodes.single { grid-template-columns: 1fr; }
.map-node {
  --node: #d7a952;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 13px;
  min-height: 64px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(160deg, rgba(29,39,52,.88), rgba(16,23,32,.88));
  text-align: left;
  transition: transform .15s, border-color .15s, background .15s;
  width: 100%;
}
button.map-node { cursor: pointer; }
button.map-node:hover { transform: translateY(-1px); border-color: color-mix(in srgb, var(--node) 60%, transparent); }
.map-node.selected, .map-node.current-choice {
  border-color: color-mix(in srgb, var(--node) 70%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--node) 25%, transparent), 0 8px 20px rgba(0,0,0,.2);
}
.map-node.locked { opacity: .48; filter: saturate(.4); }
.map-node.cleared { opacity: .78; }
.map-node .node-icon {
  flex: 0 0 auto;
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 9px;
  background: color-mix(in srgb, var(--node) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--node) 35%, transparent);
  font-size: 16px;
}
.map-node .node-body { min-width: 0; }
.map-node .node-title { font-size: 13px; font-weight: 650; color: #eae2d1; line-height: 1.25; }
