  border-radius: 99px;
  padding: 2px 7px;
  white-space: nowrap;
}
.map-node.boss { min-height: 76px; background: linear-gradient(150deg, rgba(94,31,31,.55), rgba(20,23,29,.92)); border-color: rgba(224,80,80,.45); }
.map-node.boss .node-title { font-size: 15px; color: #f1c5b8; }
.map-node.unknown { justify-content: center; align-items: center; color: var(--faint); font-size: 11px; min-height: 58px; border-style: dashed; background: rgba(15,21,29,.45); }
