/* ───────────────────────── toast ───────────────────────── */
#toast-root {
  position: fixed;
  left: 50%;
  bottom: max(14px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 120;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  width: min(560px, calc(100vw - 24px));
}
.toast {
  max-width: 100%;
  padding: 9px 15px;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: rgba(17, 24, 33, .97);
  color: var(--text);
  font-size: 11.5px;
  line-height: 1.4;
  text-align: center;
  box-shadow: 0 10px 28px rgba(0,0,0,.45);
  animation: toastIn .22s ease both;
}
.toast.good { border-color: rgba(111,207,151,.4); color: #bfe9cd; }
.toast.bad { border-color: rgba(224,93,93,.4); color: #f0b0a9; }
.toast.gold { border-color: rgba(217,176,95,.45); color: var(--gold-soft); }
.toast.fade { animation: toastOut .25s ease both; }

/* ───────────────────────── animations ───────────────────────── */
@keyframes screenIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes modalIn { from { opacity: 0; transform: translateY(10px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { from { opacity: 1; } to { opacity: 0; transform: translateY(6px); } }
@keyframes unitIn { from { opacity: 0; transform: scale(.9); } to { opacity: 1; transform: none; } }
@keyframes unitOut { from { opacity: 1; } to { opacity: 0; transform: scale(.85); } }
